#include <vector>
#include <algorithm>

using namespace std;

class Solution {
public:
    vector<int> minDifference(vector<int>& nums, vector<vector<int>>& queries) {
        int n = nums.size();
        vector<vector<int>> pref(n + 1, vector<int>(101, 0));

        for (int i = 0; i < n; ++i) {
            for (int v = 1; v <= 100; ++v) {
                pref[i + 1][v] = pref[i][v];
            }
            pref[i + 1][nums[i]]++;
        }

        vector<int> ans;
        ans.reserve(queries.size());

        for (const auto& q : queries) {
            int l = q[0], r = q[1];
            int prev = -1;
            int minDiff = 1000;

            for (int v = 1; v <= 100; ++v) {
                if (pref[r + 1][v] - pref[l][v] > 0) {
                    if (prev != -1) {
                        minDiff = min(minDiff, v - prev);
                    }
                    prev = v;
                }
            }
            ans.push_back(minDiff != 1000 ? minDiff : -1);
        }
        return ans;
    }
};

class Solution {
    public int[] minDifference(int[] nums, int[][] queries) {
        int n = nums.length;
        int[][] pref = new int[n + 1][101];

        for (int i = 0; i < n; ++i) {
            for (int v = 1; v <= 100; ++v) {
                pref[i + 1][v] = pref[i][v];
            }
            pref[i + 1][nums[i]]++;
        }

        int[] ans = new int[queries.length];
        for (int q = 0; q < queries.length; ++q) {
            int l = queries[q][0], r = queries[q][1];
            int prev = -1;
            int minDiff = 1000;

            for (int v = 1; v <= 100; ++v) {
                if (pref[r + 1][v] - pref[l][v] > 0) {
                    if (prev != -1) {
                        minDiff = Math.min(minDiff, v - prev);
