var minDifference = function(nums, queries) {
    const n = nums.length;
    const pref = Array.from({ length: n + 1 }, () => new Int32Array(101));

    for (let i = 0; i < n; ++i) {
        pref[i + 1].set(pref[i]);
        pref[i + 1][nums[i]]++;
    }

    const ans = new Int32Array(queries.length);
    for (let q = 0; q < queries.length; ++q) {
        const [l, r] = queries[q];
        let prev = -1;
        let minDiff = 1000;

        for (let v = 1; v <= 100; ++v) {
            if (pref[r + 1][v] - pref[l][v] > 0) {
                if (prev !== -1) {
                    minDiff = Math.min(minDiff, v - prev);
                }
                prev = v;
            }
        }
        ans[q] = minDiff !== 1000 ? minDiff : -1;
    }
    return Array.from(ans);
};
